// EliteShipCatalogCheck: every ship design of the catalog (GENERATED by
// tools/colonization_lab/ship_designer.py) becomes a coherent runtime
// ShipDescriptor through the ONE generic builder:
//   - drive units fill exactly the main slots of the design's physical model,
//     generator groups bind real reactor modules, ship services bind modules;
//   - descriptor physics reproduce the designer's numbers (thrust / mass);
//   - every installed unit is a module, every schematic node an installed item;
//   - module ids are unique; repair doctrine reaches the modules.
// usage: EliteShipCatalogCheck [catalog.json]
#include <cmath>
#include <iomanip>
#include <iostream>
#include <set>

#include "src/game/ship/descriptors/GenericShipDescriptorBuilder.h"

namespace
{
int failures = 0;

void check(bool ok, const std::string& what)
{
    std::cout << (ok ? "PASS " : "FAIL ") << what << "\n";
    if (!ok)
        ++failures;
}
} // namespace

int main(int argc, char** argv)
{
    using namespace game::catalog::ships;
    auto& catalog = const_cast<ShipDesignCatalog&>(ShipDesignCatalog::instance());
    const std::string path = argc > 1 ? argv[1] : "src/assets/data/ships/ship_catalog_3126.json";
    if (catalog.ships().empty())
        check(catalog.load(path), "ship catalog loads (" + path + ")");
    check(catalog.ships().size() >= 17, std::to_string(catalog.ships().size()) + " ship designs (17 classes + variants)");

    std::set<std::string> classes;
    for (const auto& s : catalog.ships())
    {
        classes.insert(s.shipClass);
        std::string error;
        const auto d = game::ship::descriptors::buildGenericShipDescriptor(s, error);
        check(d.has_value(), s.id + ": descriptor builds" + (error.empty() ? "" : " (" + error + ")"));
        if (!d)
            continue;
        const auto& loadout = d->loadouts.front();
        std::set<std::string> ids;
        bool unique = true;
        for (const auto& m : d->modules)
            unique = ids.insert(m.moduleId).second && unique;
        int units = 0;
        for (const auto& item : s.installed)
            units += game::ship::descriptors::moduleCountOf(item);
        check(unique && static_cast<int>(d->modules.size()) == units,
              s.id + ": " + std::to_string(d->modules.size()) + " modules = installed units (bulk positions one each), ids unique");
        bool slotsBound = loadout.propulsionModuleIds.size() == loadout.propulsionSlots.size();
        for (std::size_t i = 0; i < loadout.propulsionSlots.size() && slotsBound; ++i)
            if (loadout.propulsionSlots[i].role != game::ship::plant::EngineSlotRole::ManoeuvreCluster)
                slotsBound = ids.count(loadout.propulsionModuleIds[i]) > 0;
        bool groupsBound = !loadout.engineReactorGroups.empty();
        for (const auto& g : loadout.engineReactorGroups)
            groupsBound = groupsBound && ids.count(g.reactorModuleId) > 0;
        check(slotsBound && groupsBound && ids.count(d->powerThermalInstallation.shipReactorModuleId) &&
                  ids.count(d->powerThermalInstallation.commonCoolingModuleId),
              s.id + ": " + s.physicalModel + " main slots, " + std::to_string(loadout.engineReactorGroups.size()) +
                  " generator groups and ship services bound to modules");
        const double accelG = d->physics.forwardMainEngineAccelerationMps2 / 9.80665;
        const double designG = s.thrustMN * 1.0e6 / (s.dryMassTonnes * 1000.0) / 9.80665;
        check(std::abs(accelG - designG) < 1.0e-3 * std::max(1.0, designG),
              s.id + ": forward main " + std::to_string(accelG) + " g at dry mass = design thrust / dry mass");
        bool nodes = true;
        for (const auto& n : s.schematicNodes)
            nodes = nodes && ids.count(game::ship::descriptors::unitModuleId(n.code, 0)) > 0;
        bool repairs = true;
        for (const auto& m : d->modules)
            if (m.subsystemId == "jump_core")
                repairs = repairs && !m.repairable;
        check(nodes && repairs, s.id + ": schematic nodes are modules; sealed jump cores are not field-repairable");
        std::cout << "     " << std::left << std::setw(34) << s.name << " " << std::setw(11) << s.physicalModel << " "
                  << std::fixed << std::setprecision(2) << accelG << " g light-dry, " << d->modules.size() << " modules, SPOF "
                  << s.singlePointsOfFailure.size() << "\n";
    }
    check(classes.size() == 18, std::to_string(classes.size()) + " economic classes covered (17 fleet classes; tankers split jump / gas)");
    std::cout << (failures ? "SHIP CATALOG CHECK: FAILED (" + std::to_string(failures) + ")" : "SHIP CATALOG CHECK: PASS") << "\n";
    return failures ? 1 : 0;
}
